uint8_t chunkOf(const Pref& p, int G) {
    // the 6 bits at position G
    if (G + 6 <= 64) return (p.hi >> (64 - G - 6)) & 0x3F;
    if (G >= 64) return (p.lo >> (64 - (G - 64) - 6)) & 0x3F;
    // straddling: G < 64 < G+6
    int hi_bits = 64 - G;
    uint8_t v = (p.hi & mask(hi_bits)) << (6 - hi_bits);
    v |= (p.lo >> (64 - (6 - hi_bits))) & mask(6-hi_bits);
    return v;
}
