bool PrefixTable::lookup(const ip6_t& ip, uint32_t& hop) const {
    for (int len = 128; len >= 0; --len) {
        if (!has_len(len)) continue;
        uint64_t mhi, mlo;
        if (len <= 64) { mhi = mask_bits(ip.hi, len); mlo = 0; }
        else { mhi = ip.hi; mlo = mask_bits(ip.lo, len-64); }
        auto it = entries_.find(FibKey{mhi, mlo, (uint8_t)len});
        if (it != entries_.end()) { hop = it->second; return true; }
    }
    return false;
}
