#include "fib.hpp"

namespace {
inline uint64_t mask_bits(uint64_t value, int len) {
    if (len <= 0) return 0;
    if (len >= 64) return ~0ULL;
    return (~0ULL << (64 - len));
}
}  // namespace

void PrefixTable::put(uint64_t hi, uint64_t lo, uint8_t len, uint32_t hop) {
    FibKey key{hi, lo, len};
    entries_[key] = hop;
    if (len < 64) len_mask_lo_ |= (1ULL << len);
    else len_mask_hi_ |= (1ULL << (len - 64));
}

void PrefixTable::clear() {
    entries_.clear();
    len_mask_lo_ = 0;
    len_mask_hi_ = 0;
}

bool PrefixTable::lookup(const ip6_t& ip, uint32_t& hop) const {
    for (int len = 128; len >= 0; --len) {
        if (!has_len(len)) continue;
        FibKey key;
        key.len = static_cast<uint8_t>(len);
        if (len <= 64) {
            key.hi = mask_bits(ip.hi, len);
            key.lo = 0;
        } else {
            key.hi = ip.hi;
            key.lo = mask_bits(ip.lo, len - 64);
        }
        auto it = entries_.find(key);
        if (it != entries_.end()) {
            hop = it->second;
            return true;
        }
    }
    return false;
}
